import {chartSamples,hourlyPoints} from './price-history.mjs';
import {marketChart} from './market-chart.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x/100),time=m=>(Math.floor(m/60)%12||12)+':'+String(m%60).padStart(2,'0')+' '+(m>=720?'PM':'AM');
let chartMode='price';
let state=null,connected=false,busy=false,selected=new URLSearchParams(location.search).get('offer'),profile='normal',noticeTimer,uncertain=null;
const route=()=>location.pathname==='/staff'||new URLSearchParams(location.search).get('view')==='inventory'?'staff':location.pathname==='/market'||['tv','simulation'].includes(new URLSearchParams(location.search).get('view'))?'market':location.pathname.startsWith('/offers/')?'offer':'shop';
function notice(text){$('notice').textContent=text;$('notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').classList.remove('show'),6500);}
function setConnection(value){connected=value;$('connection').textContent=value?'● Live shared session':'○ Disconnected · purchases disabled';$('connection').className=value?'online':'offline';render();}
function update(next){if(!state||next.generation!==state.generation||next.revision>=state.revision){state=next;render();}}
async function command(type,payload={}){
 if(!connected||busy){notice('Wait for a live connection and the previous action.');return;}
 if(uncertain){notice('Retry the previous uncertain operation before continuing.');return;}
 const body={id:crypto.randomUUID(),generation:state.generation,revision:state.revision,type,payload};
 return transmit(body);
}
async function transmit(body){busy=true;render();try{
 const response=await fetch('/api/commands',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(data.snapshot)update(data.snapshot);
 if(!response.ok){uncertain=null;throw new Error(data.error);}
 uncertain=null;notice(body.type==='purchase'?'Order accepted at '+money(data.result.priceCents)+'. Staff can fulfill it.':'Shared session updated.');return data;
 }catch(e){if(e instanceof TypeError){uncertain=body;notice('Connection interrupted. Retry the same operation to check its outcome.');setConnection(false);}else notice(e.message);}
 finally{busy=false;render();}}
const events=new EventSource('/api/events');events.addEventListener('snapshot',e=>{try{update(JSON.parse(e.data));setConnection(true);}catch{notice('Could not read shared state.');}});events.onerror=()=>setConnection(false);
fetch('/api/session').then(r=>{if(!r.ok)throw Error('Session unavailable');return r.json();}).then(update).catch(()=>setConnection(false));
function navigate(href){history.pushState({},'',href);selected=new URLSearchParams(location.search).get('offer');render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.hash&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigate(a.href);}});window.addEventListener('popstate',()=>{selected=new URLSearchParams(location.search).get('offer');render();});
const disabled=()=>!connected||busy||!!uncertain;
const button=(action,label,attrs='',off=false)=>'<button data-action="'+action+'" '+attrs+' '+(off||(action==='retry'?busy:disabled())?'disabled':'')+'>'+label+'</button>';
function activity(){return '<section class="panel activity"><div class="panel-title"><h2>Exchange Tape</h2><span>CONFIRMED EVENTS</span></div>'+(state.events.length?state.events.slice(0,12).map(e=>'<div class="event"><time>'+time(e.at)+'</time><span class="event-dot '+e.type+'"></span><span>'+esc(e.text)+'</span></div>').join(''):'<p class="muted">Waiting for the first event. Review a batch at the staff desk.</p>')+'</section>';}
function stats(){const live=state.offers.filter(o=>o.available);return '<div class="stats"><div><span>AVAILABLE UNITS</span><strong>'+live.reduce((n,o)=>n+o.available,0)+'</strong></div><div><span>ACTIVE OFFERS</span><strong>'+live.length+'</strong></div><div><span>SIMULATED ORDERS</span><strong>'+state.orders.length+'</strong></div><div><span>COLLECTION CUTOFF</span><strong>'+time(state.cutoff)+'</strong></div></div>';}
function badge(o){return '<span class="badge '+(o.available?'good':'')+'">'+esc(o.status)+'</span>';}
function card(o){return '<article class="food"><a href="/offers/'+encodeURIComponent(o.offerId)+'"><div class="photo"><img src="'+esc(o.image)+'" alt="'+esc(o.name)+'"><span class="symbol">'+o.symbol+'</span></div><div class="food-body">'+badge(o)+'<h2>'+esc(o.name)+'</h2><p class="muted">'+esc(o.category)+'</p><div class="price">'+money(o.current_cents)+(o.current_cents<o.original_cents?'<s>'+money(o.original_cents)+'</s>':'')+'</div><p class="savings">'+(o.current_cents<o.original_cents?'Save '+money(o.original_cents-o.current_cents)+' · '+(100*(1-o.current_cents/o.original_cents)).toFixed(1)+'%':'Regular Menu Price')+'</p><div class="card-bottom"><span>'+o.available+' available</span><span>View Offer ↗</span></div></div></a></article>';}
function chart(o){if(!o.available)return '';const points=chartSamples(o.priceEvents),end=o.terminalAt??Math.min(state.minute,o.cutoff-o.fulfillment_buffer_minutes,o.observedAt+state.policy.max_count_age_minutes),start=points[0].at,span=Math.max(10,o.cutoff-start),x=t=>35+Math.max(0,t-start)/span*630,y=p=>165-(p/o.original_cents)*130;
 let path='';for(let i=0;i<points.length;i++){const p=points[i];if(p.at>end)break;path+=(path?' L':'M')+x(p.at)+' '+y(p.price);const next=points[i+1];if(!next||next.at>end)path+=' H'+x(end);}
 return '<svg class="chart" viewBox="0 0 700 210" role="img" aria-label="Dynamic confirmed price history"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4ace94" stop-opacity=".2"/><stop offset="1" stop-color="#4ace94" stop-opacity="0"/></linearGradient></defs>'+[.4,.7,1].map(v=>'<line x1="35" x2="665" y1="'+y(o.original_cents*v)+'" y2="'+y(o.original_cents*v)+'" stroke="#26332c"/><text x="40" y="'+(y(o.original_cents*v)-8)+'">'+money(o.original_cents*v)+'</text>').join('')+'<path d="'+path+'" fill="none" stroke="#4ace94" stroke-width="3"/>'+hourlyPoints(o.priceEvents,end).map(p=>'<circle cx="'+x(p.at)+'" cy="'+y(p.price)+'" r="4" fill="#4ace94"><title>'+time(p.at)+' · '+money(p.price)+'</title></circle>').join('')+'<text x="35" y="200">'+time(start)+'</text><text x="560" y="200">'+time(o.cutoff)+'</text></svg><p class="muted small">Confirmed prices only · '+esc(o.label)+' · series ends when unavailable</p>';}
function shop(){return '<div class="hero"><span class="eyebrow">THE FOOD EXCHANGE</span><h1>Your Next Bite.<br><em>A Better Price.</em></h1><p>Fresh offers from Connections Cafe. Watch the market, find your favorite, and make every bite count.</p><a class="link-button" href="/market">Watch the Exchange ↗</a></div>'+stats()+'<div class="section-heading"><h2>On the Board</h2><span class="muted">Exact batch offers · live confirmed prices</span></div><div class="food-grid">'+state.offers.map(card).join('')+'</div>';}
function detail(){const id=decodeURIComponent(location.pathname.slice('/offers/'.length)),o=state.offers.find(o=>o.offerId===id);if(!o)return '<h1>Offer Not Found</h1><p>This offer is no longer part of this demo session.</p><a href="/shop">Browse Current Offers</a>';
return '<a class="back" href="/shop">← Back to Shop</a><div class="detail"><div><img class="detail-photo" src="'+esc(o.image)+'" alt="'+esc(o.name)+'"></div><section class="panel">'+badge(o)+'<p class="eyebrow">'+esc(o.symbol)+' / '+esc(o.offerId)+'</p><h1>'+esc(o.name)+'</h1><div class="large-price">'+money(o.current_cents)+'</div><p class="savings">'+(o.current_cents<o.original_cents?'Save '+money(o.original_cents-o.current_cents)+' from '+money(o.original_cents):'Regular Price '+money(o.original_cents))+'</p><p>'+o.available+' available · Collect before '+time(o.cutoff)+'</p><p class="muted">New orders close at '+time(o.cutoff-o.fulfillment_buffer_minutes)+'. A basket does not reserve stock.</p><p class="small muted">Ingredient and allergen details have not been supplied. This is a simulated offer.</p><form id="purchase"><label>Quantity<input name="quantity" type="number" min="1" max="'+Math.max(1,Math.min(20,o.available))+'" value="1" required></label>'+button('purchase','Confirm Simulated Purchase','data-offer="'+o.offerId+'"',!o.available)+'</form><a class="back" href="/market?offer='+encodeURIComponent(o.offerId)+'">View This Batch on the Market ↗</a></section></div><section class="panel"><div class="panel-title"><h2>Confirmed Price History</h2><span>UPDATED '+time(o.priceEvents.at(-1).at)+'</span></div>'+chart(o)+'</section>';}
function market(){const o=state.offers.find(o=>o.offerId===selected)??state.offers[0];return '<div class="section-heading"><div><span class="eyebrow">MARKETBITE TERMINAL / 01</span><h1>Food, in Motion.</h1></div>'+button('fullscreen','Fullscreen ↗')+'</div>'+stats()+marketChart(state,chartMode,selected)+'<div class="terminal-grid"><section class="panel quotes"><div class="panel-title"><h2>Live Offers</h2><span>USD / CONFIRMED</span></div><div class="table-scroll"><table><thead><tr><th>OFFER</th><th>PRICE</th><th>SAVINGS</th><th>UNITS</th><th>STATUS</th></tr></thead><tbody>'+state.offers.map(b=>'<tr class="'+(b.offerId===o.offerId?'selected':'')+'"><td><a href="/market?offer='+encodeURIComponent(b.offerId)+'"><b>'+b.symbol+'</b><small>'+esc(b.name)+' · '+esc(b.label)+'</small></a></td><td>'+money(b.current_cents)+'</td><td class="savings">'+money(b.original_cents-b.current_cents)+'</td><td>'+b.available+'</td><td>'+badge(b)+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel selected-offer"><div class="panel-title"><h2>'+o.symbol+' <span class="muted">/ '+esc(o.label)+'</span></h2>'+badge(o)+'</div><h3>'+esc(o.name)+'</h3><div class="large-price">'+money(o.current_cents)+'</div><p class="savings">'+(100*(1-o.current_cents/o.original_cents)).toFixed(1)+'% savings from regular price</p>'+chart(o)+'<div class="metadata"><span>COUNT OBSERVED '+time(o.observedAt)+'</span><span>PICKUP '+time(o.cutoff)+'</span></div><a class="link-button" href="/offers/'+encodeURIComponent(o.offerId)+'">Buy This Exact Offer ↗</a></section></div><div class="ticker" aria-label="Current food prices">'+state.offers.map(b=>'<span><b>'+b.symbol+'</b> '+money(b.current_cents)+' <em>'+b.available+' LEFT</em></span>').join('')+'</div>'+activity();}
function reviewHTML(o){const r=o.review;if(!r)return '<p class="muted">Prices adjust with stock and time. Review the next adjustment.</p>';return '<h3>'+esc(r.status)+'</h3><p>'+esc(r.reason)+'</p>'+(r.missing_inputs.length?'<p>Missing: '+r.missing_inputs.map(esc).join(', ')+'</p>':'')+(r.rows.length?'<div class="table-scroll"><table><thead><tr><th>PRICE</th><th>EXPECTED GAIN</th><th>WORST GAIN</th><th>GATES</th></tr></thead><tbody>'+r.rows.map(row=>'<tr><td>'+money(row.price_cents)+'</td><td>'+money(row.expected_gain_cents)+'</td><td>'+money(row.worst_gain_cents)+'</td><td>'+Object.entries(row.gates).filter(([,v])=>!v).map(([k])=>esc(k.replaceAll('_',' '))).join(', ')+(row.admissible?'All pass':'')+'</td></tr>').join('')+'</tbody></table></div>':'')+(r.evaluation_completed&&!o.window_committed&&!o.pending?button('authorize',r.status!=='HOLD'?'Authorize Price '+money(r.price_cents):'Keep Current Price','data-offer="'+o.offerId+'" data-review="'+r.id+'"'):'');}
function staff(){const o=state.offers.find(o=>o.offerId===selected)??state.offers[0];return '<div class="section-heading"><div><span class="eyebrow">OPERATIONS / SIMULATED STAFF WORKSPACE</span><h1>Cafe Desk.</h1><p class="muted">Demo controls · no staff authentication or live checkout</p></div>'+button('pauseAll','Pause All Offers')+'</div><section class="panel clock-controls"><div><strong>'+time(state.minute)+'</strong><span class="muted"> Shared demo clock · '+(state.clock.playing?'running':'paused')+'</span></div><div class="actions">'+button('clock',state.clock.playing?'Pause':'Run Clock')+button('advance','+5 minutes','data-minutes="5"')+button('advance','+30 minutes','data-minutes="30"')+button('reset','Restart Demo')+'</div></section><div class="staff-grid"><section class="panel"><div class="panel-title"><h2>Batches</h2><span>'+state.offers.length+' TRACKED</span></div>'+state.offers.map(b=>'<a class="batch-row '+(b.offerId===o.offerId?'selected':'')+'" href="/staff?offer='+encodeURIComponent(b.offerId)+'"><div><b>'+esc(b.name)+'</b><small>'+esc(b.label)+' · '+b.available+' available</small></div>'+badge(b)+'</a>').join('')+'</section><section class="panel"><div class="panel-title"><h2>'+esc(o.name)+'</h2>'+badge(o)+'</div><p class="small muted">'+esc(o.offerId)+' · '+'Dynamic pricing · every 30 minutes'+'</p><div class="actions">'+button('approval',o.safe_and_approved?'Pause Offer':'Approve / Resume','data-offer="'+o.offerId+'"',!!o.closed)+button('close','End Offer','data-offer="'+o.offerId+'"',!!o.closed)+'</div><form id="inventory-form" data-offer="'+o.offerId+'"><div class="fields"><label>Physical Count<input name="quantity" type="number" min="0" max="500" value="'+o.physical_units+'" required></label><label>Reserved<input name="reserved" type="number" min="0" value="'+o.reserved_units+'" required></label><label>Protected<input name="protected" type="number" min="0" value="'+o.protected_units+'" required></label><label>Buffer<input name="buffer" type="number" min="0" value="'+o.buffer_units+'" required></label></div><div class="actions">'+button('recount','Reconcile Count','data-offer="'+o.offerId+'"')+button('allocations','Save Allocations','data-offer="'+o.offerId+'"')+button('restock','Receive 4 Fresh','data-offer="'+o.offerId+'"')+button('remove','Remove 1','data-offer="'+o.offerId+'"',o.physical_units<=o.reserved_units+o.protected_units+o.buffer_units)+'</div></form><p class="small muted">Recounts update dynamic stock pressure. Fresh stock receives a new batch. Observed '+time(o.observedAt)+'.</p><hr><label>Pricing Preview<select id="profile"><option value="normal" '+(profile==='normal'?'selected':'')+'>Stock and Time</option><option value="weak" '+(profile==='weak'?'selected':'')+'>Stock and Time (same policy)</option><option value="missing" '+(profile==='missing'?'selected':'')+'>Missing Evidence</option></select></label>'+button('review','Review Pricing','data-offer="'+o.offerId+'"',!!o.pending)+reviewHTML(o)+(o.pending?'<div class="pending"><h3>'+esc(o.pending.state==='unknown'?'Checkout Uncertain':'Awaiting Mock Checkout')+'</h3><p>Recommended '+money(o.pending.review.price_cents)+' · published '+money(o.current_cents)+'. Purchases paused until resolved.</p><div class="actions">'+(o.pending.state==='unknown'?button('checkout','Reconcile Provider Result','data-action-type="reconcile" data-offer="'+o.offerId+'"'):button('checkout','Acknowledge','data-action-type="ack" data-offer="'+o.offerId+'"')+button('checkout','Reject Update','data-action-type="reject" data-offer="'+o.offerId+'"')+button('checkout','Simulate Timeout','data-action-type="unknown" data-offer="'+o.offerId+'"'))+'</div></div>':'')+'</section></div><section class="panel"><div class="panel-title"><h2>Mock Orders</h2><span>RESERVATION → FULFILLMENT</span></div>'+(state.orders.length?state.orders.slice().reverse().map(order=>'<div class="order"><div><b>'+esc(order.offerId)+'</b><small>'+order.quantity+' × '+money(order.priceCents)+' · '+esc(order.status)+' · '+esc(order.id.slice(0,8))+'</small></div>'+(order.status==='accepted'?button('fulfill','Fulfill','data-order="'+order.id+'"'):'')+'</div>').join(''):'<p class="muted">No orders yet. Make a simulated purchase in Shop.</p>')+'</section>'+activity();}
let focusBookmark=null,renderedGeneration=null;
function rememberFocus(){
 const active=document.activeElement;
 if(!active?.closest('#app'))return;
 const attrs=['id','name','data-action','data-offer','data-order','data-action-type','data-minutes','data-review','data-mode','href'];
 const key=Object.fromEntries(attrs.filter(a=>active.hasAttribute(a)).map(a=>[a,active.getAttribute(a)]));
 if(!Object.keys(key).length)return;
 const editing=active.matches('input,select');
 focusBookmark={key,editing,value:editing?active.value:null,path:location.pathname+location.search,generation:renderedGeneration,draft:editing&&active.form?[...active.form.elements].filter(el=>el.name).map(el=>[el.name,el.value]):[]};
}
function restoreFocus(){
 if(!focusBookmark)return;
 if(focusBookmark.path!==location.pathname+location.search||focusBookmark.generation!==state.generation){focusBookmark=null;$('app').focus({preventScroll:true});return;}
 const {key,editing,value}=focusBookmark;
 const target=[...$('app').querySelectorAll('input,select,button,a')].find(el=>Object.entries(key).every(([k,v])=>el.getAttribute(k)===v));
 if(!target){focusBookmark=null;$('app').focus({preventScroll:true});return;}
 if(target.disabled)return;
 if(editing){for(const [name,draft] of focusBookmark.draft){const field=target.form?.elements.namedItem(name);if(field)field.value=draft;}target.value=value;}
 target.focus({preventScroll:true});
}
function render(){if(!state)return;rememberFocus();const active=route();$('clock').textContent=time(state.minute);document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===(active==='offer'?'shop':active))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('app').setAttribute('aria-busy',String(busy));$('app').innerHTML=(uncertain?'<div class="banner">An operation outcome is uncertain. '+button('retry','Retry same operation')+'</div>':'')+(!connected?'<div class="banner">Disconnected. Showing cached session; purchases and staff mutations are disabled.</div>':'')+(active==='shop'?shop():active==='market'?market():active==='staff'?staff():detail());restoreFocus();renderedGeneration=state.generation;}
$('app').addEventListener('change',e=>{if(e.target.id==='profile')profile=e.target.value;});
$('app').addEventListener('submit',e=>e.preventDefault());
$('app').addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,id=target.dataset.offer,o=state.offers.find(o=>o.offerId===id),form=$('inventory-form'),fields=form?Object.fromEntries(new FormData(form)):{};
 if(action==='chartMode'){chartMode=target.dataset.mode;render();return;}
 if(action==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();return;}
 if(action==='retry'){if(uncertain)await transmit(uncertain);return;}
 if(action==='purchase'){const f=$('purchase');if(!f.reportValidity())return;await command('purchase',{offer:id,quantity:Number(new FormData(f).get('quantity')),checkoutVersion:o.checkoutVersion});return;}
 if(['recount','allocations'].includes(action)&&!form.reportValidity())return;
 const payload=action==='clock'?{playing:!state.clock.playing,speed:state.clock.speed}:action==='advance'?{minutes:Number(target.dataset.minutes)}:action==='recount'?{offer:id,quantity:Number(fields.quantity)}:action==='allocations'?{offer:id,reserved:Number(fields.reserved),protected:Number(fields.protected),buffer:Number(fields.buffer)}:action==='restock'?{offer:id,quantity:4}:action==='remove'?{offer:id,quantity:1}:action==='approval'?{offer:id,approved:!o.safe_and_approved}:action==='review'?{offer:id,profile}:action==='authorize'?{offer:id,review:target.dataset.review}:action==='checkout'?{offer:id,operation:o.pending.id,action:target.dataset.actionType}:action==='fulfill'?{order:target.dataset.order}:{offer:id};await command(action,payload);
});
$('app').addEventListener('focusout',()=>setTimeout(()=>{if(!document.activeElement?.closest('#app')&&!busy)focusBookmark=null;},0));
